/**
 * The "updated 3 days ago" line on every card is generated by a script, which
 * makes it the kind of thing that rots silently: somebody adds a world and
 * forgets `npm run stamp`, or a shallow clone regenerates the file into
 * nothing, and the only symptom is a date quietly missing from a card nobody
 * was looking at.
 *
 * So: the generated file has to cover the registry, and the labels have to say
 * what they mean.
 */
import { describe, expect, it } from "vitest";
import { WORLDS } from "@/worlds/registry";
import { WORLD_UPDATED } from "@/worlds/updated";
import { byFreshest, changeLabel, exactLabel, sinceLabel, updatedAt } from "@/worlds/freshness";

const DAY = 86_400_000;
const NOW = Date.parse("2026-08-07T12:00:00Z");
const ago = (ms: number) => new Date(NOW - ms).toISOString();

describe("world freshness", () => {
  it("has a date for every world in the registry", () => {
    const missing = WORLDS.filter((w) => !WORLD_UPDATED[w.key]).map((w) => w.key);
    expect(
      missing,
      `run \`npm run stamp\` — no date for: ${missing.join(", ")}`,
    ).toEqual([]);
  });

  it("carries no dates for worlds that no longer exist", () => {
    const keys = new Set(WORLDS.map((w) => w.key));
    expect(Object.keys(WORLD_UPDATED).filter((k) => !keys.has(k))).toEqual([]);
  });

  it("stores parseable ISO dates that are not in the future", () => {
    for (const [key, iso] of Object.entries(WORLD_UPDATED)) {
      const t = Date.parse(iso);
      expect(Number.isFinite(t), `${key}: ${iso} is not a date`).toBe(true);
      // A day of slack for clock skew between a committer and this machine.
      expect(t, `${key} is stamped in the future`).toBeLessThan(Date.now() + DAY);
    }
  });

  it("reads a recent date in words", () => {
    expect(sinceLabel(ago(0), NOW)).toBe("today");
    expect(sinceLabel(ago(3 * 3600_000), NOW)).toBe("today");
    expect(sinceLabel(ago(1.5 * DAY), NOW)).toBe("yesterday");
    expect(sinceLabel(ago(3 * DAY), NOW)).toBe("3 days ago");
    expect(sinceLabel(ago(9 * DAY), NOW)).toBe("last week");
    expect(sinceLabel(ago(21 * DAY), NOW)).toBe("3 weeks ago");
    expect(sinceLabel(ago(50 * DAY), NOW)).toBe("last month");
    expect(sinceLabel(ago(120 * DAY), NOW)).toBe("4 months ago");
  });

  it("falls back to a month and year once it is old news", () => {
    const old = sinceLabel(ago(500 * DAY), NOW);
    expect(old).toMatch(/2025/);
  });

  it("never says a negative number when a commit is stamped ahead of us", () => {
    expect(sinceLabel(new Date(NOW + 5 * DAY).toISOString(), NOW)).toBe("today");
  });

  it("says nothing rather than something wrong for a missing date", () => {
    expect(sinceLabel(null)).toBeNull();
    expect(sinceLabel("not a date")).toBeNull();
    expect(exactLabel(undefined)).toBeNull();
    expect(updatedAt("no-such-world")).toBeNull();
  });

  /**
   * The card's date and the changelog's date answer different questions. The
   * card wants one coarse word; the log has six entries that all happened
   * "today" and has to say which came first.
   */
  it("puts a clock on every entry in the log", () => {
    /* Local time, because "time of day" means the reader's day. Asserted as a
       shape rather than a literal so the suite does not depend on TZ. */
    expect(changeLabel(ago(0), NOW)).toMatch(/^today at \d{1,2}:\d{2}( ?[ap]m)?$/i);
    expect(changeLabel(ago(1.5 * DAY), NOW)).toMatch(/^yesterday at /);
    expect(changeLabel(ago(3 * DAY), NOW)).toMatch(/^3 days ago at /);
  });

  it("drops the relative word once it stops helping, and keeps the clock", () => {
    /* "3 weeks ago at 14:32" is a worse way of writing a date than the date. */
    const older = changeLabel(ago(21 * DAY), NOW);
    expect(older).not.toMatch(/ago/);
    expect(older).toMatch(/ at /);
    // Same year, so no year in it; a different year has to say which.
    expect(older).not.toMatch(/2026/);
    expect(changeLabel(ago(500 * DAY), NOW)).toMatch(/2025/);
  });

  it("never reports a commit stamped ahead of this clock as being in the past", () => {
    expect(changeLabel(new Date(NOW + 5 * DAY).toISOString(), NOW)).toMatch(/^today at /);
  });

  it("says nothing rather than something wrong for a missing log date", () => {
    expect(changeLabel(null)).toBeNull();
    expect(changeLabel("not a date")).toBeNull();
  });

  it("sorts freshest first, and unknowns last", () => {
    const sorted = WORLDS.map((w) => w.key).sort(byFreshest);
    const times = sorted.map((k) => Date.parse(updatedAt(k) ?? "0"));
    for (let i = 1; i < times.length; i++) {
      expect(times[i - 1], `${sorted[i - 1]} should not be older than ${sorted[i]}`)
        .toBeGreaterThanOrEqual(times[i]);
    }
  });
});

/**
 * The changelog behind each card's date is generated by the same script, and
 * rots the same way: a world renamed, a `source` path moved, or somebody
 * forgetting `npm run stamp`. The failure is quiet — a card opens an empty
 * panel — so check the shape here rather than discover it in a demo.
 */
describe("world changelogs", () => {
  it("has history for every world that has a date", async () => {
    const { WORLD_CHANGES } = await import("@/worlds/changes");
    const dated = WORLDS.filter((w) => WORLD_UPDATED[w.key]);
    const missing = dated.filter((w) => !WORLD_CHANGES[w.key]?.length).map((w) => w.key);
    expect(missing, `run \`npm run stamp\` — no history for: ${missing.join(", ")}`).toEqual([]);
  });

  it("carries no history for worlds that no longer exist", async () => {
    const { WORLD_CHANGES } = await import("@/worlds/changes");
    const keys = new Set(WORLDS.map((w) => w.key));
    expect(Object.keys(WORLD_CHANGES).filter((k) => !keys.has(k))).toEqual([]);
  });

  it("agrees with the dates — the newest commit IS the stamp", async () => {
    const { WORLD_CHANGES } = await import("@/worlds/changes");
    for (const w of WORLDS) {
      const newest = WORLD_CHANGES[w.key]?.[0];
      if (!newest) continue;
      expect(newest.iso, `${w.key}: card date and newest commit disagree`).toBe(
        WORLD_UPDATED[w.key],
      );
    }
  });

  it("gives every entry a usable sha, date and subject", async () => {
    const { WORLD_CHANGES, REPO_URL } = await import("@/worlds/changes");
    expect(REPO_URL).toMatch(/^https:\/\/github\.com\//);
    for (const [key, list] of Object.entries(WORLD_CHANGES)) {
      for (const c of list) {
        expect(c.sha, `${key}: bad sha`).toMatch(/^[0-9a-f]{7,40}$/);
        expect(Number.isFinite(Date.parse(c.iso)), `${key}: bad date`).toBe(true);
        expect(c.subject.length, `${key}: empty subject`).toBeGreaterThan(0);
      }
    }
  });

  it("lists commits newest first", async () => {
    const { WORLD_CHANGES } = await import("@/worlds/changes");
    for (const [key, list] of Object.entries(WORLD_CHANGES)) {
      const times = list.map((c) => Date.parse(c.iso));
      for (let i = 1; i < times.length; i++) {
        expect(times[i - 1], `${key} is out of order`).toBeGreaterThanOrEqual(times[i]);
      }
    }
  });
});
